const list = document.querySelector("#task-list");
const empty = document.querySelector("#empty");
const form = document.querySelector("#add-form");
const input = document.querySelector("#new-title");
const estimateInput = document.querySelector("#new-estimate");
const errorBox = document.querySelector("#error");

function showError(message) {
  errorBox.textContent = message ?? "";
  errorBox.hidden = !message;
}

async function api(path, options) {
  const res = await fetch(path, { headers: { "Content-Type": "application/json" }, ...options });
  if (!res.ok) throw new Error((await res.json().catch(() => ({}))).error ?? `Request failed (${res.status})`);
  return res.status === 204 ? null : res.json();
}

async function guarded(fn) {
  try {
    showError("");
    await fn();
  } catch (err) {
    showError(err.message);
  }
}

function render(tasks) {
  list.replaceChildren(
    ...tasks.map((task) => {
      const li = document.createElement("li");
      const box = document.createElement("input");
      box.type = "checkbox";
      box.checked = Boolean(task.done);
      box.setAttribute("aria-label", `Done: ${task.title}`);
      box.addEventListener("change", () =>
        guarded(async () => {
          await api(`/api/tasks/${task.id}`, { method: "PATCH", body: JSON.stringify({ done: box.checked }) });
          await refresh();
        }),
      );
      const text = document.createElement("span");
      text.textContent = task.title;
      const remove = document.createElement("button");
      remove.type = "button";
      remove.textContent = "Delete";
      remove.addEventListener("click", () =>
        guarded(async () => {
          await api(`/api/tasks/${task.id}`, { method: "DELETE" });
          await refresh();
        }),
      );
      li.append(box, text);
      if (task.estimate != null) {
        const est = document.createElement("span");
        est.className = "estimate";
        est.textContent = `Est: ${task.estimate}`;
        li.append(est);
      }
      li.append(remove);
      return li;
    }),
  );
  empty.hidden = tasks.length > 0;
}

async function refresh() {
  render(await api("/api/tasks"));
}

form.addEventListener("submit", (event) => {
  event.preventDefault();
  return guarded(async () => {
    const body = { title: input.value };
    if (estimateInput.value !== "") body.estimate = Number(estimateInput.value);
    await api("/api/tasks", { method: "POST", body: JSON.stringify(body) });
    input.value = "";
    estimateInput.value = "";
    await refresh();
  });
});

guarded(refresh);

