import assert from "node:assert/strict";
import { DatabaseSync } from "node:sqlite";
import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { after, before, describe, it } from "node:test";
import { createApp } from "../src/app.js";
import { openDb } from "../src/db.js";

describe("tasks API", () => {
  let server;
  let base;

  before(async () => {
    server = createApp(openDb()).listen(0);
    await new Promise((resolve) => server.once("listening", resolve));
    base = `http://127.0.0.1:${server.address().port}`;
  });
  after(() => server.close());

  const json = (path, method, body) =>
    fetch(base + path, { method, headers: { "Content-Type": "application/json" }, body: body && JSON.stringify(body) });

  it("starts empty", async () => {
    const res = await fetch(`${base}/api/tasks`);
    assert.deepEqual(await res.json(), []);
  });

  it("creates, lists, updates and deletes a task", async () => {
    const created = await json("/api/tasks", "POST", { title: "  buy milk " });
    assert.equal(created.status, 201);
    const task = await created.json();
    assert.equal(task.title, "buy milk");
    assert.equal(task.done, 0);

    const done = await (await json(`/api/tasks/${task.id}`, "PATCH", { done: true })).json();
    assert.equal(done.done, 1);
    assert.equal(done.title, "buy milk");

    const all = await (await fetch(`${base}/api/tasks`)).json();
    assert.equal(all.length, 1);

    assert.equal((await json(`/api/tasks/${task.id}`, "DELETE")).status, 204);
    assert.deepEqual(await (await fetch(`${base}/api/tasks`)).json(), []);
  });

  it("rejects an empty title", async () => {
    const res = await json("/api/tasks", "POST", { title: "   " });
    assert.equal(res.status, 400);
  });

  it("returns 404 for a task that does not exist", async () => {
    assert.equal((await json("/api/tasks/999", "PATCH", { done: true })).status, 404);
    assert.equal((await json("/api/tasks/999", "DELETE")).status, 404);
  });
});

describe("task estimates", () => {
  let server;
  let base;

  before(async () => {
    server = createApp(openDb()).listen(0);
    await new Promise((resolve) => server.once("listening", resolve));
    base = `http://127.0.0.1:${server.address().port}`;
  });
  after(() => server.close());

  const json = (path, method, body) =>
    fetch(base + path, { method, headers: { "Content-Type": "application/json" }, body: body && JSON.stringify(body) });
  const list = async () => (await fetch(`${base}/api/tasks`)).json();

  it("POST with and without estimate", async () => {
    const a = await json("/api/tasks", "POST", { title: "a", estimate: 2.5 });
    assert.equal(a.status, 201);
    assert.equal((await a.json()).estimate, 2.5);
    const b = await json("/api/tasks", "POST", { title: "b" });
    assert.equal(b.status, 201);
    assert.equal((await b.json()).estimate, null);
    const z = await json("/api/tasks", "POST", { title: "zero", estimate: 0 });
    assert.equal(z.status, 201);
    assert.equal((await z.json()).estimate, 0);
    const all = await list();
    assert.ok(all.every((t) => "estimate" in t));
  });

  it("PATCH estimate only leaves title and done; null clears", async () => {
    const t = await (await json("/api/tasks", "POST", { title: "keep" })).json();
    await json(`/api/tasks/${t.id}`, "PATCH", { done: true });
    const p = await (await json(`/api/tasks/${t.id}`, "PATCH", { estimate: 4 })).json();
    assert.equal(p.estimate, 4);
    assert.equal(p.title, "keep");
    assert.equal(p.done, 1);
    const z = await (await json(`/api/tasks/${t.id}`, "PATCH", { estimate: 0 })).json();
    assert.equal(z.estimate, 0);
    const c = await (await json(`/api/tasks/${t.id}`, "PATCH", { estimate: null })).json();
    assert.equal(c.estimate, null);
    assert.equal(c.title, "keep");
  });

  it("rejects invalid estimates on POST and PATCH", async () => {
    const before = (await list()).length;
    for (const bad of ["abc", -1]) {
      const res = await json("/api/tasks", "POST", { title: "bad", estimate: bad });
      assert.equal(res.status, 400);
      assert.equal((await res.json()).error, "estimate must be a non-negative number");
    }
    assert.equal((await list()).length, before);

    const t = await (await json("/api/tasks", "POST", { title: "orig", estimate: 1 })).json();
    for (const bad of ["abc", -1]) {
      const res = await json(`/api/tasks/${t.id}`, "PATCH", { estimate: bad, title: "changed" });
      assert.equal(res.status, 400);
    }
    const after = (await list()).find((x) => x.id === t.id);
    assert.equal(after.estimate, 1);
    assert.equal(after.title, "orig");
  });
});

describe("estimate migration", () => {
  it("adds the column to an old database and is idempotent", () => {
    const path = join(mkdtempSync(join(tmpdir(), "taskly-")), "old.db");
    const old = new DatabaseSync(path);
    old.exec(`CREATE TABLE tasks (
      id INTEGER PRIMARY KEY, title TEXT NOT NULL,
      done INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
      INSERT INTO tasks (title, done, created_at) VALUES ('old', 0, '2020-01-01');`);
    old.close();

    const db = openDb(path);
    const rows = db.prepare("SELECT * FROM tasks").all();
    assert.equal(rows.length, 1);
    assert.equal(rows[0].estimate, null);
    db.close();
    assert.doesNotThrow(() => openDb(path).close());
  });
});
